macro_rules! deps {
    () => {
        RawRwLock!();
    };
}

macro_rules! RwLock {
    () => {
        deps!();
        # [doc = " A reader-writer lock"] # [doc = ""] # [doc = " This type of lock allows a number of readers or at most one writer at any"] # [doc = " point in time. The write portion of this lock typically allows modification"] # [doc = " of the underlying data (exclusive access) and the read portion of this lock"] # [doc = " typically allows for read-only access (shared access)."] # [doc = ""] # [doc = " This lock uses a task-fair locking policy which avoids both reader and"] # [doc = " writer starvation. This means that readers trying to acquire the lock will"] # [doc = " block even if the lock is unlocked when there are writers waiting to acquire"] # [doc = " the lock. Because of this, attempts to recursively acquire a read lock"] # [doc = " within a single thread may result in a deadlock."] # [doc = ""] # [doc = " The type parameter `T` represents the data that this lock protects. It is"] # [doc = " required that `T` satisfies `Send` to be shared across threads and `Sync` to"] # [doc = " allow concurrent access through readers. The RAII guards returned from the"] # [doc = " locking methods implement `Deref` (and `DerefMut` for the `write` methods)"] # [doc = " to allow access to the contained of the lock."] # [doc = ""] # [doc = " # Fairness"] # [doc = ""] # [doc = " A typical unfair lock can often end up in a situation where a single thread"] # [doc = " quickly acquires and releases the same lock in succession, which can starve"] # [doc = " other threads waiting to acquire the rwlock. While this improves throughput"] # [doc = " because it doesn't force a context switch when a thread tries to re-acquire"] # [doc = " a rwlock it has just released, this can starve other threads."] # [doc = ""] # [doc = " This rwlock uses [eventual fairness](https://trac.webkit.org/changeset/203350)"] # [doc = " to ensure that the lock will be fair on average without sacrificing"] # [doc = " throughput. This is done by forcing a fair unlock on average every 0.5ms,"] # [doc = " which will force the lock to go to the next thread waiting for the rwlock."] # [doc = ""] # [doc = " Additionally, any critical section longer than 1ms will always use a fair"] # [doc = " unlock, which has a negligible impact on throughput considering the length"] # [doc = " of the critical section."] # [doc = ""] # [doc = " You can also force a fair unlock by calling `RwLockReadGuard::unlock_fair`"] # [doc = " or `RwLockWriteGuard::unlock_fair` when unlocking a mutex instead of simply"] # [doc = " dropping the guard."] # [doc = ""] # [doc = " # Differences from the standard library `RwLock`"] # [doc = ""] # [doc = " - Supports atomically downgrading a write lock into a read lock."] # [doc = " - Task-fair locking policy instead of an unspecified platform default."] # [doc = " - No poisoning, the lock is released normally on panic."] # [doc = " - Only requires 1 word of space, whereas the standard library boxes the"] # [doc = "   `RwLock` due to platform limitations."] # [doc = " - Can be statically constructed."] # [doc = " - Does not require any drop glue when dropped."] # [doc = " - Inline fast path for the uncontended case."] # [doc = " - Efficient handling of micro-contention using adaptive spinning."] # [doc = " - Allows raw locking & unlocking without a guard."] # [doc = " - Supports eventual fairness so that the rwlock is fair on average."] # [doc = " - Optionally allows making the rwlock fair by calling"] # [doc = "   `RwLockReadGuard::unlock_fair` and `RwLockWriteGuard::unlock_fair`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use parking_lot::RwLock;"] # [doc = ""] # [doc = " let lock = RwLock::new(5);"] # [doc = ""] # [doc = " // many reader locks can be held at once"] # [doc = " {"] # [doc = "     let r1 = lock.read();"] # [doc = "     let r2 = lock.read();"] # [doc = "     assert_eq!(*r1, 5);"] # [doc = "     assert_eq!(*r2, 5);"] # [doc = " } // read locks are dropped at this point"] # [doc = ""] # [doc = " // only one write lock may be held, however"] # [doc = " {"] # [doc = "     let mut w = lock.write();"] # [doc = "     *w += 1;"] # [doc = "     assert_eq!(*w, 6);"] # [doc = " } // write lock is dropped here"] # [doc = " ```"] pub type RwLock < T > = lock_api :: RwLock < RawRwLock , T > ;
    };
}

RwLock!()